'use strict';
let purchaseGenre='';
function utilityLabel(u){return u?u.name+' · '+u.provider:'Utenza non disponibile'}
function renderPayments(){
 if(!ready)return;
 const active=state.bills.filter(b=>!b.archived),paid=active.filter(b=>C.billStatus(state,b,today()).paid),pending=active.filter(b=>!C.billStatus(state,b,today()).paid),filter=$('#billStatusFilter').value,account=$('#billAccountFilter').value;
 $('#billAccountFilter').innerHTML=options(state.accounts.filter(a=>!a.paymentProvider).map(a=>a.name),account);
 $('#billSummary').innerHTML=`<div class="kpis"><div class="card"><small>Da pagare / confermare</small><strong>${pending.length}</strong><small>${euro(pending.reduce((v,b)=>v+b.amount,0))} · promemoria, esclusi dalle spese</small></div><div class="card"><small>Pagamenti riconciliati o confermati</small><strong>${euro(paid.reduce((v,b)=>v+b.amount,0))}</strong><small>${paid.length} bollette · già comprese nei movimenti</small></div><div class="card"><small>Utenze attive</small><strong>${state.utilities.filter(u=>u.active!==false).length}</strong></div></div>`;
 const type=$('#utilityTypeFilter').value;
 $('#utilityTypeFilter').innerHTML=options(C.utilityTypes,type,'Tutte le utenze');
 const rows=state.bills.filter(b=>{let status=C.billStatus(state,b,today()),u=state.utilities.find(u=>u.id===b.utilityId),a=C.billAccount(state,b);return (filter==='archived'?b.archived:!b.archived)&&(filter!=='paid'||status.paid)&&(filter!=='pending'||!status.paid)&&(filter!=='overdue'||!status.paid&&b.due<today())&&(!account||a?.name===account)&&(!type||u?.type===type)}).sort((a,b)=>a.due.localeCompare(b.due));
 $('#billRows').innerHTML=rows.length?rows.map(b=>{let u=state.utilities.find(u=>u.id===b.utilityId),a=C.billAccount(state,b),status=C.billStatus(state,b,today());return `<article class="bill-card ${status.paid?'bill-paid':status.red?'bill-reminder':'bill-automatic'}"><div class="section-head"><h3>${esc(b.provider)} · ${euro(b.amount)}</h3><span class="badge">${esc(status.label)}</span></div><p>${esc(u?.type||'')} · ${esc(a?.name||'Conto mancante')}<br>Fattura ${esc(b.invoiceNo||'senza numero')} · Emessa ${esc(b.issued)} · Scadenza <b>${esc(b.due)}</b></p>${!status.paid&&status.automatic?'<p class="small">'+(u?.autoDebit?'Addebito automatico previsto':'Pagamento gestito altrove')+' · Non ancora confermato. L’app non esegue pagamenti.</p>':''}<div class="toolbar"><button class="btn" data-bill-edit="${esc(b.id)}">Apri / modifica</button>${!status.paid&&!b.archived?`<button class="btn primary" data-bill-pay="${esc(b.id)}">Verifica / conferma pagamento</button>`:''}${b.paymentId?`<button class="btn" data-edit="${esc(b.paymentId)}">Apri addebito</button>`:''}${b.docId?`<button class="btn" data-view-doc="${esc(b.docId)}">Documento</button>`:''}<button class="btn" data-bill-archive="${esc(b.id)}">${b.archived?'Ripristina promemoria':'Archivia'}</button></div></article>`}).join(''):'<p class="empty">Nessuna bolletta per questa ricerca. Registra una bolletta o acquisisci il suo PDF / foto.</p>';
 $('#utilityList').innerHTML=state.utilities.map(u=>`<div class="row"><div class="row-text"><b>${esc(u.name)}</b><small>${esc(u.type)} · ${esc(u.provider)} · Addebito: ${esc(state.accounts.find(a=>a.id===u.accountId)?.name||'conto mancante')}${u.autoDebit?' · Domiciliazione prevista':''}${u.managedExternally?' · Gestita altrove':''}${u.active===false?' · Non attiva':''}${u.inferred?' · Rilevata dalle causali, verifica il contratto':''}</small></div><button class="btn" data-utility-edit="${esc(u.id)}">Modifica utenza</button><button class="btn" data-bill-new="${esc(u.id)}">＋ Bolletta</button></div>`).join('')||'<p class="empty">Aggiungi un’utenza e scegli il conto di addebito. I fornitori riconosciuti nei movimenti esistenti vengono proposti al primo aggiornamento.</p>';
 let used=new Set(state.bills.map(b=>b.paymentId).filter(Boolean)),debits=state.movements.filter(m=>m.type==='Spesa'&&!used.has(m.id)&&(C.providerInfo(m.description)||m.category==='Bollette')&&(!account||m.account===account));
 $('#billUnmatched').innerHTML=debits.length?`<p class="small">${debits.length} addebiti già presenti nei conti, senza bolletta associata. Sono già conteggiati nelle spese: aggiungi il documento per riconciliarli.</p><div class="table-wrap"><table><thead><tr><th>Data</th><th>Causale</th><th>Conto</th><th>Importo</th><th></th></tr></thead><tbody>${debits.map(m=>`<tr><td>${esc(C.formatDate(m.date))}</td><td>${esc(m.description)}</td><td>${esc(m.account)}</td><td>${euro(-m.amount)}</td><td><button class="btn" data-bill-from="${esc(m.id)}">Associa bolletta</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="small">Nessun addebito di utenza non associato per il conto selezionato.</p>';
 renderPurchaseGenres();
}
function renderPurchaseGenres(){renderPurchaseGenreChoices()}

function editUtility(id){if(!requiredAccounts())return;let old=state.utilities.find(u=>u.id===id),base=old||{name:'',provider:'',type:'Energia elettrica',accountId:state.accounts.find(a=>a.name==='Fineco CC')?.id||state.accounts[0].id,reference:'',autoDebit:false,managedExternally:false,active:true};modal(`<form id="utilityForm"><h2>${old?'Modifica':'Nuova'} utenza</h2><label>Nome dell’utenza<input name="name" value="${esc(base.name)}" required maxlength="120" placeholder="Es. Luce di casa"></label><label>Fornitore<input name="provider" value="${esc(base.provider)}" required maxlength="120"></label><label>Genere di utenza<select name="type">${options(C.utilityTypes,base.type,null)}</select></label><label>Conto di addebito<select name="accountId">${state.accounts.filter(a=>!a.paymentProvider).map(a=>`<option value="${esc(a.id)}" ${a.id===base.accountId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Codice cliente / POD / PDR, facoltativo<input name="reference" value="${esc(base.reference)}"></label><label class="check"><input name="autoDebit" type="checkbox" ${base.autoDebit?'checked':''}> Domiciliazione già attiva presso il fornitore / banca</label><label class="check"><input name="managedExternally" type="checkbox" ${base.managedExternally?'checked':''}> Pagamento gestito altrove: non evidenziare promemoria rossi</label><label class="check"><input name="active" type="checkbox" ${base.active!==false?'checked':''}> Utenza attiva</label><p class="small">Queste impostazioni descrivono il contratto: non attivano addebiti e non confermano il pagamento. Le bollette già registrate conservano il proprio conto di addebito.</p><div class="dialog-actions"><button type="button" class="btn" data-close>Annulla</button><button class="btn primary">Salva utenza</button></div></form>`);$('#utilityForm').onsubmit=async e=>{e.preventDefault();let f=formValue(e.target),u={...base,...f,id:old?.id||C.uid(),name:f.name.trim(),provider:f.provider.trim(),autoDebit:!!f.autoDebit,managedExternally:!!f.managedExternally,active:!!f.active,inferred:false};if(await change(s=>{if(old)s.utilities[s.utilities.findIndex(x=>x.id===old.id)]=u;else s.utilities.push(u)}))$('#modal').close()}}
function startBillDocument(){if(!requiredAccounts())return;startDocument();$('#docKind').value='Bolletta / fattura';docDraft.kind='Bolletta / fattura'}
function editBill(id='',utilityId='',movementId='',fromDocument=false){
 if(!requiredAccounts())return;
 const old=state.bills.find(b=>b.id===id),m=state.movements.find(m=>m.id===movementId),read=fromDocument?C.parseBill(docDraft.text,today()):{},known=read.provider?state.utilities.filter(u=>C.normalized(u.provider)===C.normalized(read.provider)):[],suggested=C.providerInfo(m?.description||''),u=state.utilities.find(u=>u.id===(old?.utilityId||utilityId))||known[0]||state.utilities.find(u=>suggested&&C.normalized(u.provider)===C.normalized(suggested.provider)),account=state.accounts.find(a=>a.id===(old?.accountId||u?.accountId))||state.accounts.find(a=>a.name===(m?.account||docDraft?.account||'Fineco CC'))||state.accounts[0];
 const b=old||{id:C.uid(),utilityId:u?.id||'new',provider:u?.provider||read.provider||suggested?.provider||'',invoiceNo:read.invoiceNo||'',issued:read.issued||m?.date||today(),due:read.due||m?.date||'',amount:read.amount|| (m?-m.amount:0),accountId:account.id};
 const html=`<form id="billForm"><h2>${fromDocument?'Controlla la bolletta letta':old?'Modifica bolletta':'Registra bolletta'}</h2><p class="small">La bolletta entra nei pagamenti solo quando è collegata a un addebito effettivo o dopo conferma manuale. La registrazione non crea una spesa.</p><div class="form-grid"><label>Utenza<select id="billUtility" name="utilityId"><option value="new" ${b.utilityId==='new'?'selected':''}>＋ Nuova utenza con questi dati</option>${state.utilities.map(u=>`<option value="${esc(u.id)}" ${u.id===b.utilityId?'selected':''}>${esc(utilityLabel(u))}</option>`).join('')}</select></label><label>Fornitore<input name="provider" required maxlength="120" value="${esc(b.provider)}"></label><label>Genere di utenza<select name="utilityType">${options(C.utilityTypes,u?.type||read.type||suggested?.type||'Altra utenza',null)}</select></label><label>Numero fattura / bolletta<input name="invoiceNo" maxlength="80" value="${esc(b.invoiceNo)}"></label><label>Data emissione<input name="issued" type="date" lang="it-IT" required value="${b.issued}"></label><label>Scadenza<input name="due" type="date" lang="it-IT" required value="${b.due}"></label><label>Totale da pagare EUR<input name="amount" type="number" min=".01" step=".01" required value="${b.amount||''}"></label><label>Conto di addebito<select name="accountId">${state.accounts.filter(a=>!a.paymentProvider).map(a=>`<option value="${esc(a.id)}" ${a.id===b.accountId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Codice cliente / POD / PDR<input name="reference" value="${esc(u?.reference||read.reference||'')}"></label></div><div id="newUtilityFlags" ${b.utilityId!=='new'?'hidden':''}><label class="check"><input name="autoDebit" type="checkbox" ${read.autoDebit?'checked':''}> Domiciliazione già attiva: attendi l’addebito, senza promemoria rosso</label><label class="check"><input name="managedExternally" type="checkbox"> Pagamento gestito altrove: senza promemoria rosso</label></div>${fromDocument?'<label class="check"><input id="billVerified" type="checkbox" required> Ho confrontato fornitore, numero, date, importo e conto con il documento originale.</label>':''}<p id="billFormError" class="inline-error" role="status"></p><div class="dialog-actions"><button type="button" class="btn" ${fromDocument?'id="cancelBillReview"':'data-close'}>Annulla</button><button class="btn primary" id="saveBill">${fromDocument?'Conferma bolletta e archivia documento':'Salva bolletta e verifica addebiti'}</button></div></form>`;
 if(fromDocument){$('#docReview').innerHTML=html;$('#cancelBillReview').onclick=()=>$('#docReview').innerHTML=''}else modal(html,true);
 $('#billUtility').onchange=e=>{let current=state.utilities.find(u=>u.id===e.target.value);$('#newUtilityFlags').hidden=!!current;if(current){let form=$('#billForm');form.elements.provider.value=current.provider;form.elements.accountId.value=current.accountId;form.elements.utilityType.value=current.type;form.elements.reference.value=current.reference||''}};
 $('#billForm').onsubmit=async e=>{e.preventDefault();let button=$('#saveBill');button.disabled=true;try{let f=formValue(e.target),next=structuredClone(state),utility=next.utilities.find(u=>u.id===f.utilityId),provider=f.provider.trim();if(fromDocument&&!$('#billVerified').checked)throw Error('Confronta i dati con il documento prima di confermare');if(!utility){utility={id:C.uid(),name:provider+' · '+f.utilityType,provider,type:f.utilityType,accountId:f.accountId,reference:f.reference.trim(),autoDebit:!!f.autoDebit,managedExternally:!!f.managedExternally,active:true};next.utilities.push(utility)}let record={...b,utilityId:utility.id,provider,invoiceNo:f.invoiceNo.trim(),issued:f.issued,due:f.due,amount:C.round(Number(f.amount)),accountId:f.accountId},files=[];
 if(fromDocument){let hash=docDraft.file?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await docDraft.file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join(''):'';record.sourceSHA256=hash;if(C.duplicateBill(next,record))throw Error('Questo documento o numero di bolletta è già registrato');let doc={id:C.uid(),name:docDraft.file?.name||provider+'-'+record.invoiceNo+'.txt',kind:'Bolletta / fattura',date:record.issued,account:next.accounts.find(a=>a.id===record.accountId).name,merchant:provider,total:record.amount,text:docDraft.text,method:docDraft.method,sourceSHA256:hash};record.docId=doc.id;next.documents.push(doc);if(docDraft.file)files.push({id:doc.id,name:doc.name,blob:docDraft.file})}
 if(m){let used=next.bills.some(x=>x.id!==record.id&&x.paymentId===m.id);if(used||C.round(-m.amount)!==record.amount||next.accounts.find(a=>a.id===record.accountId)?.name!==m.account)throw Error('L’addebito scelto non coincide con conto e importo della bolletta');record.paymentId=m.id;record.paymentMode=m.manualPayment?'manual':'bank'}
 if(record.paymentId&&!C.validPayment({...next,bills:[record]},record)){delete record.paymentId;delete record.paymentMode}
 next=C.registerBill(next,record);await commit(next,files);if(fromDocument)$('#docModal').close();else $('#modal').close();showPage('bills');toast(C.validPayment(state,state.bills.find(x=>x.id===record.id))?'Bolletta registrata e addebito riconciliato. Nessuna spesa duplicata.':'Bolletta registrata: pagamento in attesa di verifica.')
 }catch(error){$('#billFormError').textContent=error.message;button.disabled=false}};
}
function reviewBillDocument(){editBill('','','',true)}
function payBill(id){let b=state.bills.find(b=>b.id===id),a=C.billAccount(state,b),used=new Set(state.bills.filter(x=>x.id!==id).map(x=>x.paymentId)),candidates=state.movements.filter(m=>m.account===a?.name&&m.type==='Spesa'&&C.round(-m.amount)===C.round(b.amount)&&!used.has(m.id)&&m.date<=today()).sort((a,b)=>b.date.localeCompare(a.date));modal(`<form id="payBillForm"><h2>Verifica il pagamento</h2><p><b>${esc(b.provider)} · ${euro(b.amount)}</b><br>Conto di addebito: ${esc(a?.name)}</p><label>Registrazione<select name="movementId"><option value="">Conferma un pagamento non ancora registrato</option>${candidates.map(m=>`<option value="${esc(m.id)}">Collega a ${esc(C.formatDate(m.date))} · ${esc(m.description)} · ${euro(-m.amount)}</option>`).join('')}</select></label><label>Data effettiva, solo per un nuovo pagamento<input name="date" type="date" lang="it-IT" value="${today()}" max="${today()}" required></label><label class="check"><input name="verified" type="checkbox" required> Confermo di aver pagato oppure verificato l’addebito selezionato.</label><p class="small">Collegare un addebito esistente non crea un’altra spesa. La conferma manuale senza addebito registra una sola uscita; una successiva importazione riconosce il pagamento se coincidono conto, importo, data entro 3 giorni e numero fattura o fornitore.</p><p id="payBillError" class="inline-error" role="status"></p><div class="dialog-actions"><button type="button" class="btn" data-close>Annulla</button><button class="btn primary" id="confirmBillPayment">Conferma pagamento</button></div></form>` ,true);$('#payBillForm').onsubmit=async e=>{e.preventDefault();let f=formValue(e.target);if(!f.verified)return;$('#confirmBillPayment').disabled=true;try{await commit(C.confirmBillPayment(state,id,{movementId:f.movementId,date:f.date,allowNew:true},today()));$('#modal').close();toast('Pagamento confermato una sola volta.')}catch(error){$('#payBillError').textContent=error.message;$('#confirmBillPayment').disabled=false}}}
$('#newUtility').onclick=()=>editUtility();$('#newBill').onclick=()=>editBill();$('#scanBill').onclick=startBillDocument;
for(const id of ['billStatusFilter','billAccountFilter','utilityTypeFilter'])$('#'+id).onchange=renderPayments;
$('#purchaseMacro').onchange=e=>{purchaseGenre=e.target.value;markPurchaseDraft()};
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;try{if(b.dataset.utilityEdit)editUtility(b.dataset.utilityEdit);if(b.dataset.billNew)editBill('',b.dataset.billNew);if(b.hasAttribute('data-purchase-genre')){purchaseGenre=b.dataset.purchaseGenre;$('#purchaseMacro').value=purchaseGenre;markPurchaseDraft()}if(b.dataset.billEdit)editBill(b.dataset.billEdit);if(b.dataset.billPay)payBill(b.dataset.billPay);if(b.dataset.billFrom)editBill('','',b.dataset.billFrom);if(b.dataset.billArchive)await change(s=>{let bill=s.bills.find(x=>x.id===b.dataset.billArchive);bill.archived=!bill.archived})}catch(error){toast(error.message)}});
